import{_ as a,o,c as r,a5 as e}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"blob 协议","description":"blob: 协议是一种特殊的 URL 方案，专门用于表示基于 Blob 对象的数据。这种 URL 格式包含一个 blob: 前缀，后面紧跟当前页面的 origin（例如 https://smartgate.changsha.gov.cn），然后是一个唯一标识符（如 2391b59。","frontmatter":{"title":"blob 协议","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"blob: 协议是一种特殊的 URL 方案，专门用于表示基于 Blob 对象的数据。这种 URL 格式包含一个 blob: 前缀，后面紧跟当前页面的 origin（例如 https://smartgate.changsha.gov.cn），然后是一个唯一标识符（如 2391b59。","sidebarWeight":77,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/blob/快速了解/blob 协议.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/blob 协议.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/blob 协议.md"}'),s={name:"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/blob 协议.md"};function n(b,t,l,g,i,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<div><h1 id="blob-协议" tabindex="-1">blob 协议 <a class="header-anchor" href="#blob-协议" aria-label="Permalink to &quot;blob 协议&quot;">​</a></h1><blockquote><p>本节目标：理解“blob 协议”的核心思路，并能把它用于实际开发或面试表达。 blob: 协议是一种特殊的 URL 方案，专门用于表示基于 Blob 对象的数据。这种 URL 格式包含一个 blob: 前缀，后面紧跟当前页面的 origin（例如 <a href="https://smartgate.changsha.gov.cn" target="_blank" rel="noreferrer">https://smartgate.changsha.gov.cn</a>），然后是一个唯一标识符（如 2391b596-9458-4501-a215-e4527d6b1f4f）。这里的 origin 起到了限定作用，确保该 Blob 数据的访问符合安全规范。 <strong>1. blob: 协议的作用</strong></p></blockquote><ul><li>blob: 协议 URL 是浏览器生成的临时资源定位符，用来引用在客户端创建的 Blob 数据。</li><li>这种 URL 不对应于服务器上任何实际文件，也不会被服务器直接访问；它只是当前浏览器会话中的一个客户端资源。</li></ul><p><strong>2. blob: 协议 URL 中的 origin</strong></p><ul><li>blob URL 中的 origin（<a href="https://smartgate.changsha.gov.cn" target="_blank" rel="noreferrer">https://smartgate.changsha.gov.cn</a>）指明了数据的来源页面。浏览器会自动将 Blob URL 的 origin 与创建它的页面 origin 绑定。</li><li><strong>安全性目的</strong>：将 Blob 与页面 origin 绑定，限制了跨域访问。只能由相同 origin 的页面来访问和使用该 Blob 数据。</li></ul><p><strong>3. Blob URL 和普通 https URL 的区别</strong></p><ul><li><strong>数据来源</strong>：<a href="https://smartgate.changsha.gov.cn" target="_blank" rel="noreferrer">https://smartgate.changsha.gov.cn</a> 是一个指向服务器上资源的标准 HTTP/HTTPS URL。而 blob: URL 则是浏览器内存中生成的，数据来源于客户端（例如通过 JavaScript 生成的 Blob 对象）。</li><li><strong>作用范围</strong>：https URL 可以被其他任何页面引用，只要符合同源策略或跨域请求规则；blob URL 仅在创建它的 origin 页面上有效。</li><li><strong>生命周期</strong>：Blob URL 是临时的，在页面刷新或手动调用 URL.revokeObjectURL 后将失效，而 https URL 则指向实际的服务器资源，通常不会失效。</li></ul><p><strong>简单总结</strong> 在你的线上环境中，这个 blob:<a href="https://smartgate.changsha.gov.cn/2391b596-9458-4501-a215-e4527d6b1f4f" target="_blank" rel="noreferrer">https://smartgate.changsha.gov.cn/2391b596-9458-4501-a215-e4527d6b1f4f</a> URL 是一个临时的 Blob 数据地址，绑定了页面的 origin。<a href="https://smartgate.changsha.gov.cn" target="_blank" rel="noreferrer">https://smartgate.changsha.gov.cn</a> 表示该数据只能被该 origin 页面访问，确保了客户端生成数据的安全性，避免了跨域风险。 这也意味着，即使你看到 <a href="https://smartgate.changsha.gov.cn" target="_blank" rel="noreferrer">https://smartgate.changsha.gov.cn</a> 出现在 blob: URL 中，这个 URL 并不真正指向服务器资源，只是表明来源和安全作用范围。</p></div>',1)])])}const f=a(s,[["render",n]]);export{p as __pageData,f as default};
